namespace Lifestone.Client.Options;

public static partial class OptionCatalog
{
    /// <summary>
    /// Play mode in the main scene: the session host and its checks (M2 wave-2 track G6; parsed by
    /// src/Lifestone.Client/Play/PlayOptions.cs). The play switch itself, <c>--play</c>, is the <see cref="Session"/> group's.
    /// </summary>
    public static OptionGroup Play() => new("Play mode", "main scene",
    [
        new("--login-check", "enter", "Run an automated login check on the bundled ACE and quit (0 = it held; implies --play; tools\\play.ps1 -Offscreen runs it on the test account): 'enter' is the whole first-login path, off-screen: the data check, the character list, select (or create 'Lifestone Smoke'), Enter, portal space, the arrival in the Training Academy, LoginComplete once, the unhide, a 5 s wait, a log off back to the character list and quit. The frame rule is judged: the run fails on any frame over 50 ms between Enter and walking (the first 3 frames after the character list appears are excluded: building that screen is the retail UI's own cost). An automated run uses only the test account: with no --account it is accounts.test, and any other --account is refused. The longer checks play movement scenarios with the game's own player between the settle and the log off, on the live server: 'academy-exit' walks to the Academy's exit portal and uses it (the server walks the player the rest of the way), 'holtburg-laps' is sent to Holtburg by a server teleport and walks three laps of a ring around its arrival point, and 'all' (also the bare --login-check) is the enter path, then the Academy exit, then the Holtburg laps, in one login. Each ends with the character back at its start; ACE must accept every move (no force-position correction, where-am-I within 0.5 m at every stop). The Academy's exit portal is quest-gated in ACE's world database: the leg asks the server mod for the Sentry's quest, stamps it when the character lacks it, uses the portal (ACE teleports the character to Holtburg: exit=teleported, required), and after the way home asks the registry and puts the quest back as it found it (the portal's own emote set erases it, so a quest found held is stamped again). The portal's emote set also graduates the character for good: its sanctuary moves to Holtburg, recalls are enabled and ten Academy quests are erased, and nothing puts those back (the run leaves the character's position and that one quest as found, nothing else). Prints '[logincheck] done ok=<true|false> enter_to_walk_max_ms=<x> holtburg_min_fps=<x|n/a> corrections=<n|n/a> where_max_m=<x|n/a> exit=<teleported|failed|n/a> quest=<put-back|unchanged|unverified|n/a> legs=<names|none> teleports=<n> leg_teleports=<n> teleport_frame_max_ms=<x|n/a> academy_objects=<n> logoff=<ok|failed> materialised=<true|false|n/a> fade_ms=<ms|n/a> objects_drawn=<n|n/a> level=<n|?> mage_char=<present|absent|pending-delete> fighter=<present|absent|pending-delete>' (level, mage_char and fighter are report-only and never fail the check: level is the character's level when the settle ends, mage_char says whether the account's character list holds 'BSD Mage', fighter whether it holds 'Holtburg Hunter'; materialised: the server created the player hidden, unhid it, its body was drawn and its own Hidden-script particles were drawn; fade_ms: the player's materialise fade measured on frames, from the first visible frame after the unhide to the first opaque one, judged between 650 and 900 ms around the UnHide script's 750 ms hook, through at least five frames of intermediate alpha, never opaque before the fade; holtburg_min_fps: the slowest one-second window of the Holtburg laps, judged against 60; teleport_frame_max_ms: the longest frame from a leg's server teleport to a second after the player is present again, judged against 50). 'throwaway' is a separate check, never part of 'all' (D59, D61, D65): it creates 'Lifestone Throwaway' on the test account through the retail character-creation screens (first trying the taken name 'Lifestone Smoke' and a creature's name, which ACE refuses in retail dialogs), enters the world at once, uses the tools panel (Where am I, Add XP 2,500 to that character only, a Places teleport to Holtburg), logs off, deletes it with the typed word, restores it, deletes it again, then enters 'Lifestone Smoke', purges the throwaway with the server mod's char purge verb and logs off, so the account ends as it began (a throwaway left by a failed run is deleted and purged first and reported as leftover=yes). Prints '[logincheck] throwaway done ok=<true|false> throwaway=<purged|failed> name_errors=<n> xp=<added|n/a> where_m=<m|n/a> place=<teleported|n/a> deletes=<n> restores=<n> list=<same|different|n/a> leftover=<yes|no> enter_to_walk_max_ms=<x|n/a> teleport_frame_max_ms=<x|n/a>' and needs the server mod installed with the purge verb. Run it with tools\\godot.ps1 -TimeoutSeconds 840 (the leg aborts itself at 600 s and allows 120 s more to recover). 'buff' (M3 2.1) is another separate check, never part of 'all': it enters 'BSD Mage' on the test account (absent: it fails and says to run --scenario=mage-build), re-seats the wand (move it to the pack, wield it in its Held location: ACE sends a server sound on a wield, none on a cast or a login, so this is the leg's fixture for the sound judge, not a gear step), runs the buff scenario in the game's session (the gear, the magic combat mode, the cycle of the profile's 24 buff lines, the forced re-buff pass, non-combat) with the game's own cast visuals, then logs off and quits; it changes the character (buffs, burned components) and uses the live server. Prints '[logincheck] buff done ok=<true|false> gear=<wielded|failed> worn=<n> cast=<ok|fizzled|failed|n/a> buffs=<active>/<wanted> rebuffed=<yes|no> forced=<yes|no> min_remaining_s=<s> levels=<line:level,..> cycle_s=<s> cast_scripts=<n> cast_sounds=<n> cast_windows=<n> cast_frame_max_ms=<x|n/a> sounds_server=<n|n/a> fizzles=<n> misses=<names|none>': judged are gear=wielded, every wanted line active, rebuffed=yes and sounds_server>=1; the cast_* fields and cast= are report-only. With --play-screenshot=PATH and no --play-screenshot-after it saves three frames with the developer HUD hidden (<stem>-1.png to -3.png, 0.1, 0.4 and 0.8 s after the forced self buff's effect). Run it with tools\\godot.ps1 -TimeoutSeconds 900 (the live cycle took 56 s for 26 casts; the leg itself stops at 600 s). In 'academy-exit', 'holtburg-laps' and 'all', sounds_hooks over the walking legs is judged (at least 1); the Academy arrival's sounds_server stays a report. 'bsd-fight' (M3 3.1) is a third separate check, never part of 'all': it enters 'BSD Mage' on the test account, goes to the Aluvian Black Spawn Den (the Places row 'Black Spawn Den (Aluvian)'), tops up the buffs and fights the Tusker Slaves and Guards on the den's arrival floor with Flame Bolt (never the drudges or the virindi in the north wing), then logs off and quits; it changes the character (experience, components) and uses the live server. Prints '[logincheck] bsd-fight done ok=<true|false> kills=<n> damage_dealt=<n> spells_cast=<n> misses=<n> xp_gained=<n> damage_taken=<n> hits_taken=<n> evades=<n> projectiles=<n|n/a> cast_frame_max_ms=<x|n/a> fight_frame_max_ms=<x|n/a> bsd_min_fps=<x|n/a> fight_s=<s|n/a>': judged are no failure, kills>=1 and damage_dealt>0 (the killing blow has no damage line, so damage_dealt is the blows before it); every other field is report-only (cast_frame_max_ms is the worst frame while a cast window is open, fight_frame_max_ms the worst frame of the fight while a cast or projectile window is open or a target is engaged, bsd_min_fps the lowest one-second window in the den; --fight-kills and --fight-seconds set the fight's limits). With --play-screenshot=PATH and no --play-screenshot-after it saves three frames with the developer HUD hidden (<stem>-bolt.png: the bolt in flight, <stem>-hit.png: its hit, <stem>-kill.png: the kill line in the chat), each logged with its trigger; a frame whose trigger never came is logged by name and not taken. Run it with tools\\godot.ps1 -TimeoutSeconds 1200 (the leg itself stops at 750 s with the default --fight-seconds). 'bsd-death' (M3 3.2) is a fourth separate check, never part of 'all': it enters 'BSD Mage' on the test account, binds it at Holtburg's lifestone, goes to the Aluvian Black Spawn Den, unbuffs it with a suicide when any enchantment but the vitae is active, dies to the tuskers unbuffed, respawns at the lifestone, goes back for its own corpse before the re-gear's top-up (M4 2.2: by 'place loc', opens it and takes everything; --death-recover-corpse and --death-recover-min-health set it), re-gears (the dropped kit items spawned again, or taken from the corpse, the wand and the five pieces wielded) and logs off; it changes the character (vitae, dropped items, a corpse in the den) and uses the live server. The bind walks the game's own player to the lifestone's use radius before the Use; --death-seconds (default 600) bounds the wait among the tuskers. With --play-screenshot=PATH and no --play-screenshot-after it saves five frames with the developer HUD hidden (<stem>-hit.png: a blow taken, the vitals down; <stem>-dead.png: the Dead motion, the death line in the chat; <stem>-corpse.png: the corpse's F745, when it comes before portal space; <stem>-lifestone.png: the arrival plus 3.5 s, the lifestone and the 75% vitals; <stem>-corpse-open.png, M4 2.2: the mage's own corpse open on the return trip, the container window listing its contents), each logged with its trigger; a frame whose trigger never came, or whose moment fell in portal space, is logged by name and not taken. Run it with tools\\godot.ps1 -TimeoutSeconds 1650 (the leg itself stops at 1205 s with the default --death-seconds). Prints '[logincheck] bsd-death done ok=<true|false> died=<n> suicides=<n> vitae=<pct> respawn=<lifestone|elsewhere|none> corpse=<n> purged=<n> protected=<n> vitals_pct=<x|n/a> gear_restored=<yes|no> worn=<n> hits_taken=<n> damage_taken=<n> evades=<n> health_min_pct=<x|n/a> death_s=<s|n/a> death_frame_max_ms=<x|n/a> fight_frame_max_ms=<x|n/a> deaths=<n> corpses_stale=<n> protection=<dispelled|expired|none> vitae_paid=<xp|n/a> vitae_after=<pct|n/a> corpse_looted=<yes|partial|no|skipped> items_recovered=<n> trip_s=<s|n/a> trip_abort=<reason|none>': judged are no failure, died=1 (exactly one death by the tuskers), respawn=lifestone (the arrival within 15 m of a lifestone object), gear_restored=yes, damage_taken>0 and hits_taken>=1; every other field is report-only, death_frame_max_ms and the corpse trip's four fields included (the trip adds up to about 110 s; the smoke step's 1650 s covers it). 'hunt' (M4 1.2) is a fifth separate check, never part of 'all': it enters 'Holtburg Hunter' on the test account (absent: it fails and says to run --scenario=fighter-build), binds at Holtburg's lifestone, goes to the hunt grounds, hunts the creatures there with the Mace (or, with --hunt-weapon=missile, the Shortbow and Arrows) until --hunt-kills kills or --hunt-seconds, returns to Holtburg with the Mace wielded and logs off; it changes the character (experience, arrows, a potion) and uses the live server. Prints '[logincheck] hunt done ok=<true|false> kills=<n> damage_dealt=<n> damage_taken=<n> hits_taken=<n> evades=<n> xp_gained=<n> fighter=<ok|wrong> swings=<n> shots=<n> hits=<n> misses=<n> returned=<yes|no> attack_frame_max_ms=<x|n/a> corpses_opened=<n> corpse_items=<n>[ frame_over_50=yes]': judged are no failure, the player alive, kills>=1 and damage_dealt>0 (the killing blow has no damage line) and, from 1.3, the weapon's own counters: melee swings>=1, missile shots>=1 and hits>=1; from 2.1 attack_frame_max_ms, the slowest frame from an attack's send to its run's Done (over 75 ms fails, over 50 ms adds frame_over_50=yes); every other field is report-only (fighter, misses, returned, and corpses_opened and corpse_items, the kill's corpse opened and listed, which the lead reads at the item's gate). --hunt-kills, --hunt-seconds, --hunt-weapon and --hunt-open-corpse set the hunt, and --loot, --loot-types, --loot-min-value and --loot-max-burden set what it takes from the corpse (M4 2.2: the line also reports looted, loot_skipped and loot_frame_max_ms, report-only until 3.1). --sell, --buy-kits and --appraise-loot (M4 3.2) set the loop's end: the sale to Renald the Elder, the purchase of Handy Healing Kits at Thelnoth Cort and the identify of each looted item, and the line also reports sold, bought, pyreals=<delta>, appraised and vendor_frame_max_ms after mode_mismatch, report-only (sold>=1 and vendor_frame_max_ms are judged at 4.2). With --play-screenshot=PATH and no --play-screenshot-after it saves the frames its weapon gives with the developer HUD hidden (melee: <stem>-swing.png, 0.3 s after the first own swing of a sequence with the target within 6 m, then <stem>-c1-combat.png, <stem>-c1-powerbar.png and <stem>-meter.png, the retail combat window, its power bar mid-charge and the target's health meter, and <stem>-corpse.png (M4 2.2: the kill's corpse open with the container window over it listing ALL its contents, taken once the window is drawn within the 2 s hold; its log line names the window's title and cell count and the corpse's ObjDesc counts, and a window that did not draw is logged by name and the frame not taken), <stem>-heal.png and <stem>-potion.png (M4 3.1: 1 s after a healing kit's use whose roll won and after a potion that restored points, each taken once with the camera framed: the vitals and the chat line after a recovery; a frame whose trigger never came is named in the leg's end note); <stem>-vendor.png (M4 3.2, either weapon: 1 s after Renald the Elder's 0062, taken whatever shows, its log line saying whether a vendor panel was visible); <stem>-arrow.png: missile, 0.1 s after the first arrow's F745 while the arrow exists), logged with its trigger, the target and the weapon's wcid. Run it with tools\\godot.ps1 -TimeoutSeconds 1500 (the leg itself stops at 780 s with the default --hunt-seconds and --sell and --buy-kits off, at 1200 s with the shop visits on, which they are by default; M4 3.2). ", OptionRole.CheckSuite),
        new("--play-frames", "DIR", "With --play-checks: save the shell's review frames (the arrival, portal space in the SmartBox, an object selected, a NotInM3 message, character information, the options with side-by-side vitals, the logout confirmation) to DIR (default docs/screenshots/m2/shell/<W>x<H>), fail on a missing, blank or wrong-sized frame, and print 'shell frames done'. The frame-time judgement is reported, not judged (the read-back stalls frames). The frames are derived from the dats and never committed.", ValueOptional: true),
        new("--retail-picking", null, "Retail's picking rules where Lifestone fixes them (default: the nearest polygon of a part, hit times in world units): a part's first hit polygon in its own order, and hit times compared in each part's own scaled local-ray units, which can pick a different object than the nearest one under the pointer (docs/avatars.md section 18)."),
        new("--retail-camera-still", null, "Retail's fixed stall step of the chase camera (default: the step is scaled by the frame time, a glitch fix): retail keeps the previous viewer when the smoothed position is under a fixed 0.0004 m from it (CameraManager::UpdateCamera, 11.4186 0x00456660, 11.6096 0x00456780), so its dead zone around the wanted point grows with the frame rate, about 7 mm at 60 Hz and 20 mm at 240 Hz. At 60 Hz or slower both are the same."),
        new("--retail-unhide-flash", null, "Retail's one opaque frame when an object or the player is unhidden after a re-hide in the middle of its materialise fade (default: that frame is not drawn; the new fade starts at full translucency): retail's older fade hook leaves translucency 0 behind while the object is hidden and the unhide's own fade hook applies a frame later (docs/avatars.md section 17)."),
        new("--retail-sphereless-missile", null, "Retail's rule for a projectile whose Setup has no collision spheres (default: it flies on its own velocity like every other projectile): retail's missile update (CPhysicsObj::UpdateObjectInternal, 11.6096 0x005161B0) keeps the origin of an object with no sphere (GetNumSphere, 0x00518B90), so such a bolt stays where it was created. All nine war-spell Setups have one sphere, so this changes nothing for them (docs/avatars.md section 17)."),
        new("--retail-cast-any-mode", null, "Send a cast through the Action API whatever the combat mode, as retail's client would (default: a cast outside the magic combat mode is refused at once on the client with a named reason, a Lifestone guard: retail's own UI cannot send one, since the spell window and the cast keys exist only in magic mode, and its client makes no mode check, so ACE refuses it with a silent UseDone after up to a 10 s wait). With this option the cast is sent and ACE refuses it."),
        new("--all-sizes", null, "With --retail-ui-checks: also place the shell at 1920x1080 (UI scale 1) and 2560x1440 (UI scale 2). Default: 800x600 only, retail's native size (several resolutions are a polish step at the end of the project)."),
        new("--play-screenshot", "PATH", "Play mode: save one PNG of the game viewport --play-screenshot-after seconds (default 5) after the player is placed in the world (present, and the physics body settled), then quit with 0 (1 when it could not be saved; with --play-checks it saves and the checks go on; with --login-check=buff and no --play-screenshot-after the buff leg saves three frames instead, <stem>-1.png to -3.png, 0.1, 0.4 and 0.8 s after its forced self buff's effect, and ends by its own verdict; with --login-check=bsd-fight and no --play-screenshot-after the fight leg saves <stem>-bolt.png, -hit.png and -kill.png the same way; with --login-check=bsd-death and no --play-screenshot-after the death leg saves <stem>-hit.png, -dead.png, -corpse.png, -lifestone.png and -corpse-open.png (M4 2.2, the return trip's open corpse) on their triggers; with --login-check=hunt and no --play-screenshot-after the hunt leg saves <stem>-swing.png (melee) or <stem>-arrow.png (missile), and for melee also -c1-combat.png, -c1-powerbar.png, -meter.png and -corpse.png (M4 2.2, the container window over the kill's open corpse)). Relative paths are taken from the repository root; never inside src/ or tests/. The frame is derived from the dats and never committed. For a review frame of a character as it is after a scenario (for example BSD Mage after --scenario=gear): tools\\play.ps1 -Character \"BSD Mage\" -Resolution 800x600 -GameArgs:'--play-screenshot=cache/m3/1-4/gear-frame.png'."),
        new("--play-screenshot-after", "S", "With --play-screenshot: the seconds to wait after the player is placed (default 5, which lets the materialise fade and the arrival's sounds and particles settle)."),
        new("--play-panel-shots", "DIR", "Play mode (M3 2.2): once the player is placed and the arrival has settled (--play-screenshot-after seconds, default 5), open each registered panel page in turn through its toolbar action, save an 800x600 PNG of each to DIR as <panelId>-<name>.png with the developer HUD hidden, close it, log each path, then quit with 0 (1 when a frame could not be saved). With no registered page it logs 'no panel registered yet' and quits. Relative paths are taken from the repository root; never inside src/ or tests/. The frames are derived from the dats and never committed. After the pages it saves the combat windows (M3 3.2: c1-combat.png, the combat window in melee mode, c1-powerbar.png, the power bar begun by hand at a placeholder level, and c2-spellcasting.png, the spellcasting window in Magic mode with the character's favourite spell bars), each shown by the UI's own mode notice so the character keeps its mode. With --play-checks it only saves and the checks go on (and --play-frames saves the panel frames under <frames dir>/panels/ itself). For the review frames of a character: tools\\play.ps1 -Character \"BSD Mage\" -Resolution 800x600 -GameArgs:'--play-panel-shots=cache/m3/2-2/panel-shots'."),
        new("--play-skip-scenarios", null, "With --play-checks (M3 4.2 p5a, C4): leave out the stand-in's fight and death scenarios (the Flame Bolt kill, and the bind, death, respawn and vitae checks), which a plain --play-checks run judges. For a --play-frames run: the review frames are taken by the checks around them, so the frames run is about 200 s shorter and its frames and judges are unchanged. A skipped scenario logs one 'skipped' line and adds no check. Needs --play-checks."),
    ], OptionScenes.Main);
}
